{
  "name": "Gatan电镜相机与能量过滤器系统",
  "name_en": "Gatan TEM Camera and Energy Filter System",
  "manufacturer": "Gatan",
  "description": "这是一套用于透射电子显微镜的Gatan成像与能量过滤系统，可管理一台或多台电镜相机，并支持K2类直接电子探测器参数设置、图像采集、分帧保存以及能量过滤器调节。它常用于TEM和冷冻电镜实验中的图像记录、剂量分割采集和零损峰对准。",
  "description_en": "This is a Gatan imaging and energy-filter system for transmission electron microscopy. It can manage one or more microscope cameras and supports K2-class direct electron detector configuration, image acquisition, frame saving, and energy filter adjustment. It is commonly used in TEM and cryo-EM experiments for image recording, dose-fractionated acquisition, and zero-loss peak alignment.",
  "tag_hints": [
    "TEM camera",
    "Gatan DigitalMicrograph",
    "direct electron detector",
    "K2 camera",
    "energy filter",
    "cryo-EM imaging",
    "dose fractionation"
  ],
  "actions": [
    {
      "action_name": "auto-hasScriptFunction",
      "description": "检查控制系统是否提供指定的脚本功能。",
      "description_en": "Check whether the control system provides a specified script function."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到相机与能量过滤器控制系统。",
      "description_en": "Connect to the camera and energy-filter control system."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与相机控制系统的连接。",
      "description_en": "Disconnect from the camera control system."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接到相机控制系统。",
      "description_en": "Reconnect to the camera control system."
    },
    {
      "action_name": "auto-send_data",
      "description": "向相机控制系统发送原始控制数据。",
      "description_en": "Send raw control data to the camera control system."
    },
    {
      "action_name": "auto-recv_data",
      "description": "从相机控制系统接收原始数据。",
      "description_en": "Receive raw data from the camera control system."
    },
    {
      "action_name": "auto-ExchangeMessages",
      "description": "与相机控制系统交换命令消息包。",
      "description_en": "Exchange command message packets with the camera control system."
    },
    {
      "action_name": "auto-GetLong",
      "description": "读取一个整数状态或参数值。",
      "description_en": "Read a single integer status or parameter value."
    },
    {
      "action_name": "auto-SendLongGetLong",
      "description": "发送一个整数参数并读取一个整数结果。",
      "description_en": "Send one integer parameter and read back one integer result."
    },
    {
      "action_name": "auto-GetDMVersion",
      "description": "获取DigitalMicrograph版本信息。",
      "description_en": "Get the DigitalMicrograph version information."
    },
    {
      "action_name": "auto-GetNumberOfCameras",
      "description": "获取系统中的相机数量。",
      "description_en": "Get the number of cameras in the system."
    },
    {
      "action_name": "auto-GetPluginVersion",
      "description": "获取相机控制插件版本信息。",
      "description_en": "Get the camera control plugin version information."
    },
    {
      "action_name": "auto-IsCameraInserted",
      "description": "检查指定相机是否处于插入工作位置。",
      "description_en": "Check whether the specified camera is inserted into its working position."
    },
    {
      "action_name": "auto-InsertCamera",
      "description": "设置指定相机插入或退出工作位置。",
      "description_en": "Set the specified camera to be inserted into or retracted from its working position."
    },
    {
      "action_name": "auto-SetReadMode",
      "description": "设置探测器读出模式和缩放参数。",
      "description_en": "Set the detector readout mode and scaling parameter."
    },
    {
      "action_name": "auto-SetShutterNormallyClosed",
      "description": "设置相机快门是否默认为常闭状态。",
      "description_en": "Set whether the camera shutter is normally closed."
    },
    {
      "action_name": "auto-SetK2Parameters",
      "description": "设置K2相机采集参数，包括读出模式、缩放、硬件处理、剂量分帧、帧时间、对齐和存帧选项。",
      "description_en": "Configure K2 camera acquisition parameters, including readout mode, scaling, hardware processing, dose fractionation, frame time, alignment, and frame saving options."
    },
    {
      "action_name": "auto-setNumGrabSum",
      "description": "设置提前返回帧数和内存抓取累加参数。",
      "description_en": "Set the early-return frame count and RAM-grab summing parameters."
    },
    {
      "action_name": "auto-getNumGrabSum",
      "description": "获取提前返回帧数和内存抓取累加参数。",
      "description_en": "Get the early-return frame count and RAM-grab summing parameters."
    },
    {
      "action_name": "auto-SetupFileSaving",
      "description": "配置图像或分帧数据的保存方式、文件命名和提前返回选项。",
      "description_en": "Configure image or frame-data saving, file naming, and early-return options."
    },
    {
      "action_name": "auto-SelectCamera",
      "description": "选择当前活动相机。",
      "description_en": "Select the active camera."
    },
    {
      "action_name": "auto-UpdateK2HardwareDarkReference",
      "description": "更新K2相机的硬件暗参考。",
      "description_en": "Update the hardware dark reference for the K2 camera."
    },
    {
      "action_name": "auto-GetEnergyFilter",
      "description": "get 能量过滤器状态。",
      "description_en": "get the energy filter state."
    },
    {
      "action_name": "auto-SetEnergyFilter",
      "description": "set 能量过滤器状态。",
      "description_en": "set the energy filter state."
    },
    {
      "action_name": "auto-GetEnergyFilterWidth",
      "description": "get 能量过滤器狭缝宽度。",
      "description_en": "get the energy filter slit width."
    },
    {
      "action_name": "auto-SetEnergyFilterWidth",
      "description": "set 能量过滤器狭缝宽度。",
      "description_en": "set the energy filter slit width."
    },
    {
      "action_name": "auto-GetEnergyFilterOffset",
      "description": "get 能量过滤器能量偏移。",
      "description_en": "get the energy filter energy offset."
    },
    {
      "action_name": "auto-SetEnergyFilterOffset",
      "description": "set 能量过滤器能量偏移。",
      "description_en": "set the energy filter energy offset."
    },
    {
      "action_name": "auto-AlignEnergyFilterZeroLossPeak",
      "description": "对准能量过滤器的零损峰。",
      "description_en": "Align the zero-loss peak of the energy filter."
    },
    {
      "action_name": "auto-GetImage",
      "description": "按指定处理模式、视场、binning和曝光时间采集图像。",
      "description_en": "Acquire an image with the specified processing mode, field of view, binning, and exposure time."
    },
    {
      "action_name": "auto-ExecuteSendCameraObjectionFunction",
      "description": "执行一个指定的相机对象控制功能，不返回测量值。",
      "description_en": "Execute a specified camera-object control function without returning a measurement value."
    },
    {
      "action_name": "auto-ExecuteGetLongCameraObjectFunction",
      "description": "执行一个相机对象功能并读取整数结果。",
      "description_en": "Execute a camera-object function and read back an integer result."
    },
    {
      "action_name": "auto-ExecuteGetDoubleCameraObjectFunction",
      "description": "执行一个相机对象功能并读取浮点结果。",
      "description_en": "Execute a camera-object function and read back a floating-point result."
    },
    {
      "action_name": "auto-ExecuteCameraObjectFunction",
      "description": "执行一个指定的相机对象功能。",
      "description_en": "Execute a specified camera-object function."
    },
    {
      "action_name": "auto-ExecuteSendScript",
      "description": "执行一条DigitalMicrograph脚本命令，不返回数值结果。",
      "description_en": "Execute a DigitalMicrograph script command without returning a numeric result."
    },
    {
      "action_name": "auto-ExecuteGetLongScript",
      "description": "执行DigitalMicrograph脚本并读取整数结果。",
      "description_en": "Execute a DigitalMicrograph script and read back an integer result."
    },
    {
      "action_name": "auto-ExecuteGetDoubleScript",
      "description": "执行DigitalMicrograph脚本并读取浮点结果。",
      "description_en": "Execute a DigitalMicrograph script and read back a floating-point result."
    },
    {
      "action_name": "auto-ExecuteScript",
      "description": "执行一条DigitalMicrograph脚本命令。",
      "description_en": "Execute a DigitalMicrograph script command."
    },
    {
      "action_name": "auto-RunScript",
      "description": "运行一个DigitalMicrograph脚本文件。",
      "description_en": "Run a DigitalMicrograph script file."
    }
  ]
}

